      out.write("                            <h5 class=\"fw-bold text-primary mb-0\">1. Encapsulation</h5>\n");
      out.write("                        </div>\n");
      out.write("                        <p class=\"text-secondary small\">\n");
      out.write("                            All entity state is encapsulated with <code>private</code> access modifiers. State mutations enforce strict business invariants:\n");
      out.write("                        </p>\n");
      out.write("                        <ul class=\"text-secondary small mb-0\">\n");
      out.write("                            <li><strong>Shelter Capacity:</strong> <code>shelter.canAccommodate(count)</code> and <code>shelter.allocate(count)</code> prevent over-allocation.</li>\n");
