      out.write("                            <li><strong>Security:</strong> User credentials are protected using salted BCrypt hashing and encapsulated in <code>PasswordUtils</code>.</li>\n");
      out.write("                        </ul>\n");
      out.write("                    </div>\n");
      out.write("                </div>\n");
      out.write("            </div>\n");
      out.write("\n");
      out.write("            <!-- 2. Inheritance -->\n");
      out.write("            <div class=\"col-md-6\">\n");
      out.write("                <div class=\"card card-theme h-100 border-start border-4 border-danger\">\n");
      out.write("                    <div class=\"card-body\">\n");
      out.write("                        <div class=\"d-flex align-items-center mb-3\">\n");
      out.write("                            <span class=\"badge bg-danger p-2 me-2\"><i class=\"bi bi-diagram-3 fs-5\"></i></span>\n");
      out.write("                            <h5 class=\"fw-bold text-danger mb-0\">2. Inheritance</h5>\n");
      out.write("                        </div>\n");
      out.write("                        <p class=\"text-secondary small\">\n");
      out.write("                            Hierarchical domain models eliminate redundant code and promote clean type reuse:\n");
      out.write("                        </p>\n");
      out.write("                        <ul class=\"text-secondary small mb-0\">\n");
      out.write("                            <li><code>BaseEntity</code> &rarr; parent class for all persistent models providing <code>id</code>, <code>createdAt</code>, and <code>updatedAt</code>.</li>\n");
