      out.write("                            <li><code>IncidentRecord</code> (abstract) &rarr; specialized by <code>DisasterReport</code> and <code>AssistanceRequest</code>.</li>\n");
      out.write("                        </ul>\n");
      out.write("                    </div>\n");
      out.write("                </div>\n");
      out.write("            </div>\n");
      out.write("\n");
      out.write("            <!-- 3. Polymorphism -->\n");
      out.write("            <div class=\"col-md-6\">\n");
      out.write("                <div class=\"card card-theme h-100 border-start border-4 border-warning\">\n");
